                )
                for site_info in dct["info"]["sites_info"]
            ]
        return cls(
            voronoi=voronoi,
            valences=dct["valences"],
            sites_map=dct["sites_map"],
            equivalent_sites=[[PeriodicSite.from_dict(psd) for psd in psl] for psl in dct["equivalent_sites"]],
