        matrix, lengths = self._matrix, self.lengths
        angles = np.zeros(3)
        for dim in range(3):
            jj = (dim + 1) % 3
            kk = (dim + 2) % 3
            angles[dim] = np.clip(np.dot(matrix[jj], matrix[kk]) / (lengths[jj] * lengths[kk]), -1, 1)
