def contract(string):
    """
    Examples:
        assert contract("1 1 1 2 2 3") == "3*1 2*2 1*3"
        assert contract("1 1 3 2 3") == "2*1 1*3 1*2 1*3".
    """
    if not string:
        return string

    tokens = string.split()
    old = tokens[0]
    count = [[1, old]]

    for tok in tokens[1:]:
        if tok == old:
            count[-1][0] += 1
        else:
            old = tok
            count.append([1, tok])

    return " ".join(f"{c}*{t}" for c, t in count)


