            self._config_dict["INCAR"].pop("GGA", None)
        elif self.xc_functional in ["PBE", "PBEsol"]:
            config_updates |= {"GGA": to_func[self.xc_functional]}
            self._config_dict["INCAR"].pop("METAGGA", None)
