                    "S6": 1.0,
                    "S8": 0.60187490,
                    "A1": 0.51559235,
                    "A2": 5.77342911,
                },
                "PBE": {
                    "S6": 1.0,
                    "S8": 0.95948085,
                    "A1": 0.38574991,
                    "A2": 4.80688534,
                },
                "PBEsol": {
                    "S6": 1.0,
                    "S8": 1.71885698,
                    "A1": 0.47901421,
                    "A2": 5.96771589,
                },
            }
            config_updates |= {"IVDW": 13, **{f"VDW_{k}": v for k, v in d4_pars[self.xc_functional].items()}}

