# Defines: class PointGroupAnalyzer, def _combine_eq_sets(equiv_sets: dict, sym_ops: dict) -> dict, def all_equivalent_atoms_of_i(idx, eq_sets, ops), def get_equivalent_atoms(self)
# Uses: copy, itertools, logging, math, warnings, collections, defaultdict, collections.abc, Sequence, fractions
